function memoMaterials(){return selectedResearchProject?[...(selectedResearchProject.interviews||[]).map(x=>({name:x.name,type:'workspace',key:String(x.id),projectId:String(x.id)})),...(selectedResearchProject.uploaded_transcripts||[]).map((x,index)=>({name:x.name,type:'uploaded',key:String(index),projectId:x.workspace_project_id?String(x.workspace_project_id):''}))]:selectedProject?[{name:selectedProject.name,type:'workspace',key:String(selected),projectId:String(selected)}]:[]}
function renderMemoSwitcher(){const picker=$('#memoInterviewSelect'),rows=memoMaterials();picker.innerHTML=(rows.length?rows.map(row=>`<option data-type="${row.type}" data-key="${escapeHtml(row.key)}" ${currentMemoMaterial&&currentMemoMaterial.type===row.type&&String(currentMemoMaterial.key)===row.key?'selected':''}>${escapeHtml(row.name)}</option>`).join(''):'<option>暂无访谈稿</option>')+'<option value="choose-project">选择研究项目…</option>';picker.disabled=false;$('#compareMaterialsBtn').disabled=false}
function renderMemo(){renderMemoSource();renderMemoSwitcher();const panel=$('#memoPanel'),memo=analysisData?.familiarity_memo;$('#memoTitle').textContent=selectedProject?.name?`${selectedProject.name} · 访谈纪要`:'访谈纪要';$('#memoStatus').textContent=memo?'已生成':'尚未生成';$('#generateMemoBtn').disabled=!selected;if(!memo){panel.innerHTML='<div class="memo-empty">点击“生成纪要”开始。</div>';$('#saveMemoBtn').disabled=true;return}$('#saveMemoBtn').disabled=false;panel.innerHTML=`<div class="memo-meta"><label><span>受访者</span><input id="memoIdentity" value="${escapeHtml(memo.participant_identity||'')}"></label><label><span>日期</span><input id="memoDate" value="${escapeHtml(memo.interview_date||'')}"></label><label><span>主题</span><input id="memoTopic" value="${escapeHtml(memo.interview_topic||'')}"></label></div><section class="memo-summary"><div class="memo-summary-head"><h3>访谈摘要</h3><button class="soft ai-action" id="generateMemoSummaryBtn"><i class="ai-ring" aria-hidden="true"></i><span>${memo.summary?'重新生成':'生成摘要'}</span></button></div><p id="memoSummary" contenteditable="true">${escapeHtml(memo.summary||'')}</p></section><details class="memo-detail" open><summary>具体观点</summary><section class="memo-viewpoints">${(memo.viewpoints||[]).map((view,index)=>`<article class="viewpoint-card" data-viewpoint="${index}"><div class="viewpoint-heading"><span class="viewpoint-number">${String(index+1).padStart(2,'0')}</span><input class="viewpoint-title" value="${escapeHtml(view.title||'')}"></div><div class="viewpoint-body"><div class="viewpoint-summary-row"><span class="viewpoint-summary" contenteditable="true">${escapeHtml(view.summary||'')}</span><span class="memo-indexes">${memoEvidenceButtons(view.evidence)}</span></div>${(view.points||[]).length?`<ul>${view.points.map((point,pointIndex)=>`<li data-point="${pointIndex}"><span class="point-text" contenteditable="true">${escapeHtml(point.text||'')}</span><span class="memo-indexes">${memoEvidenceButtons(point.evidence)}</span></li>`).join('')}</ul>`:''}</div></article>`).join('')||'<div class="memo-empty">尚未提取到核心观点</div>'}</section></details>`;panel.querySelectorAll('[data-evidence-number]').forEach(button=>button.onclick=()=>renderMemoSource(Number(button.dataset.evidenceNumber)));$('#generateMemoSummaryBtn').onclick=generateMemoSummary}
function comparisonRecords(){return selectedResearchProject?.material_comparisons||[]}
function comparisonRecordLabel(item,index){const stamp=item.saved_at||item.generated_at;return item.name||(stamp?new Date(stamp*1000).toLocaleString('zh-CN'):`第 ${index+1} 次`)}
function closeComparisonHistory(){const list=$('#comparisonHistoryList');list.hidden=true;$('#comparisonHistoryToggle').setAttribute('aria-expanded','false')}
function renderComparisonHistory(){const records=comparisonRecords(),toggle=$('#comparisonHistoryToggle'),list=$('#comparisonHistoryList');let index=currentComparison?records.findIndex(item=>item.id&&item.id===currentComparison.id):-1;if(index<0&&Number.isInteger(currentComparison?._recordIndex))index=currentComparison._recordIndex;toggle.textContent=(index>=0&&records[index]?comparisonRecordLabel(records[index],index):'历史结果')+' ▾';toggle.disabled=!records.length;list.innerHTML=records.map((item,i)=>`<div class="comparison-history-row${i===index?' active':''}"><button type="button" class="comparison-history-record" data-index="${i}" title="双击重命名">${escapeHtml(comparisonRecordLabel(item,i))}</button><button type="button" class="comparison-history-delete" data-index="${i}" title="删除记录" aria-label="删除${escapeHtml(comparisonRecordLabel(item,i))}">×</button></div>`).reverse().join('');list.querySelectorAll('.comparison-history-record').forEach(button=>{button.onclick=()=>loadComparisonRecord(Number(button.dataset.index));button.ondblclick=()=>renameComparison(Number(button.dataset.index),button)});list.querySelectorAll('.comparison-history-delete').forEach(button=>button.onclick=()=>deleteComparison(Number(button.dataset.index)));closeComparisonHistory()}
function switchFamiliarityMode(mode){const comparison=mode==='comparison';$('#memoWorkspace').hidden=comparison;$('#comparisonWorkspace').hidden=!comparison;$('#comparisonTopActions').hidden=!comparison;$('#memoModeBtn').classList.toggle('active',!comparison);$('#comparisonModeBtn').classList.toggle('active',comparison);if(comparison){if(currentComparison&&currentComparison._researchProjectId!==(selectedResearchProject?.id||''))currentComparison=null;renderComparisonHistory();if(currentComparison)renderComparison();else{$('#saveComparisonBtn').disabled=true;$('#comparisonPanel').innerHTML='<div class="memo-empty">请选择材料开始比较</div>'}}else renderMemo()}
function collectMemo(){const memo=analysisData?.familiarity_memo;if(!memo)return;memo.participant_identity=$('#memoIdentity')?.value.trim()||'';memo.interview_date=$('#memoDate')?.value.trim()||'';memo.interview_topic=$('#memoTopic')?.value.trim()||'';memo.summary=$('#memoSummary')?.innerText.trim()||'';document.querySelectorAll('.viewpoint-card').forEach(card=>{const view=memo.viewpoints[Number(card.dataset.viewpoint)];if(!view)return;view.title=card.querySelector('.viewpoint-title')?.value.trim()||'';view.summary=card.querySelector('.viewpoint-summary')?.innerText.trim()||'';card.querySelectorAll('li[data-point]').forEach(item=>{const point=view.points[Number(item.dataset.point)];if(point)point.text=item.querySelector('.point-text')?.innerText.trim()||''})})}
async function generateMemo(){if(!selected){toast('请先打开一份访谈稿');return}const button=$('#generateMemoBtn');setAiLoading(button,true);$('#memoStatus').textContent='正在生成纪要…';try{const result=await api(`/api/projects/${selected}/familiarity-memo`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh:!!analysisData?.familiarity_memo})});analysisData.familiarity_memo=result.memo;renderMemo();toast('访谈纪要已生成')}catch(e){$('#memoStatus').textContent='生成失败';toast(e.message)}finally{setAiLoading(button,false)}}
async function saveMemo(){if(!analysisData?.familiarity_memo)return;collectMemo();await saveAnalysis(false);renderMemo();toast('访谈纪要已保存')}
async function generateMemoSummary(){if(!selected||!analysisData?.familiarity_memo)return;collectMemo();const button=$('#generateMemoSummaryBtn');setAiLoading(button,true);try{const result=await api(`/api/projects/${selected}/familiarity-summary`,{method:'POST'});analysisData.familiarity_memo.summary=result.summary;renderMemo();toast('访谈摘要已生成')}catch(e){toast(e.message)}finally{setAiLoading(button,false)}}
function openComparisonDialog(){const rows=memoMaterials(),list=$('#comparisonMaterialList');if(rows.length<2){toast('至少需要两份访谈稿');return}list.innerHTML=rows.map(row=>`<label class="comparison-choice"><input type="checkbox" data-type="${row.type}" data-key="${escapeHtml(row.key)}" data-project-id="${escapeHtml(row.projectId)}"><span>${escapeHtml(row.name)}</span></label>`).join('');updateComparisonCount();$('#comparisonDialog').showModal()}
function updateComparisonCount(){const count=document.querySelectorAll('#comparisonMaterialList input:checked').length;$('#comparisonCount').textContent=`已选择 ${count} 份`;$('#startComparisonBtn').disabled=count<2}
async function generateComparison(){const choices=[...document.querySelectorAll('#comparisonMaterialList input:checked')],button=$('#startComparisonBtn');if(choices.length<2)return;setAiLoading(button,true);try{const ids=[];for(const choice of choices){let projectId=choice.dataset.projectId;if(!projectId&&choice.dataset.type==='uploaded'){const prepared=await api(`/api/research-projects/${selectedResearchProject.id}/uploaded/${choice.dataset.key}/prepare`,{method:'POST'});projectId=prepared.project_id}if(projectId)ids.push(projectId)}if(ids.length<2)throw new Error('至少需要两份可用访谈稿');const result=await api('/api/material-comparisons',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_ids:ids,research_project_id:selectedResearchProject?.id||''})});currentComparison={...result.comparison,_saved:false,_researchProjectId:selectedResearchProject?.id||''};comparisonCategory='common';$('#comparisonDialog').close();switchFamiliarityMode('comparison');toast('材料比较已生成，保存后可在比较记录中查看')}catch(e){toast(e.message)}finally{setAiLoading(button,false)}}
function comparisonEvidenceButtons(perspective){return (perspective.evidence||[]).map(number=>`<button class="evidence-index comparison-evidence" data-project-id="${escapeHtml(perspective.project_id)}" data-evidence-number="${Number(number)}" title="${escapeHtml(perspective.material_name)} · 查看原文">${Number(number)}</button>`).join('')}
function renderComparison(){if(!currentComparison)return;const labels={common:'共性',differences:'差异',unique:'个别观点'},items=currentComparison[comparisonCategory]||[],panel=$('#comparisonPanel');$('#saveComparisonBtn').disabled=!!currentComparison._saved||!selectedResearchProject;panel.innerHTML=`<div class="comparison-tabs">${Object.entries(labels).map(([key,label])=>`<button class="${key===comparisonCategory?'active':''}" data-comparison-tab="${key}">${label}</button>`).join('')}</div><div class="comparison-list">${items.length?items.map((item,index)=>`<article class="comparison-item"><div class="viewpoint-heading"><span class="viewpoint-number">${String(index+1).padStart(2,'0')}</span><h3>${escapeHtml(item.title||'')}</h3></div><p>${escapeHtml(item.summary||'')}</p>${(item.perspectives||[]).map(view=>`<div class="comparison-perspective"><b>${escapeHtml(view.material_name||'')}</b><span>${escapeHtml(view.text||'')}</span><span class="memo-indexes">${comparisonEvidenceButtons(view)}</span></div>`).join('')}</article>`).join(''):'<div class="memo-empty">没有发现这一类比较结果</div>'}</div>`;panel.querySelectorAll('[data-comparison-tab]').forEach(button=>button.onclick=()=>{comparisonCategory=button.dataset.comparisonTab;renderComparison()});panel.querySelectorAll('.comparison-evidence').forEach(button=>button.onclick=()=>openComparisonEvidence(button.dataset.projectId,Number(button.dataset.evidenceNumber)))}
function askComparisonName(initial='',title='保存比较结果',label='比较名称'){return new Promise(resolve=>{const dialog=$('#textDialog'),input=$('#textDialogInput');$('#textDialogTitle').textContent=title;$('#textDialogLabel').firstChild.textContent=label;input.value=initial;input.required=true;input.maxLength=80;dialog.returnValue='';dialog.addEventListener('close',()=>{const name=dialog.returnValue==='default'?input.value.trim():'';input.required=false;resolve(name)},{once:true});dialog.showModal();input.focus();input.select()})}
async function saveComparison(){if(!currentComparison||currentComparison._saved)return;if(!selectedResearchProject){toast('请从研究项目中进入材料熟悉后保存');return}const name=await askComparisonName();if(!name)return;const button=$('#saveComparisonBtn');button.disabled=true;try{const clean={...currentComparison,name};delete clean._saved;delete clean._researchProjectId;const result=await api(`/api/research-projects/${selectedResearchProject.id}/material-comparisons`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({comparison:clean})});currentComparison={...result.comparison,_saved:true,_researchProjectId:selectedResearchProject.id,_recordIndex:result.count-1};selectedResearchProject.material_comparisons=selectedResearchProject.material_comparisons||[];selectedResearchProject.material_comparisons.push(result.comparison);const stored=researchProjects.find(item=>item.id===selectedResearchProject.id);if(stored)stored.material_comparisons=selectedResearchProject.material_comparisons;renderComparisonHistory();renderComparison();toast('本次比较结果已保存')}catch(e){button.disabled=false;toast(e.message)}}
function loadComparisonRecord(index){const record=comparisonRecords()[index];if(!record)return;currentComparison={...record,_saved:true,_researchProjectId:selectedResearchProject?.id||'',_recordIndex:index};comparisonCategory='common';$('#comparisonHistoryToggle').textContent=comparisonRecordLabel(record,index)+' ▾';$('#comparisonHistoryList').querySelectorAll('.comparison-history-row').forEach(row=>row.classList.toggle('active',Number(row.querySelector('.comparison-history-record').dataset.index)===index));renderComparison()}
function renameComparison(index,button){const record=comparisonRecords()[index];if(!selectedResearchProject||!record||!button)return;const input=document.createElement('input');input.className='comparison-history-input';input.type='text';input.maxLength=80;input.value=comparisonRecordLabel(record,index);input.setAttribute('aria-label','比较记录名称');button.replaceWith(input);input.focus();input.select();let done=false;input.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();input.blur()}else if(event.key==='Escape'){event.preventDefault();done=true;input.replaceWith(button);button.focus()}};input.onblur=async()=>{if(done)return;done=true;const name=input.value.trim();if(!name||name===record.name){input.replaceWith(button);return}try{const result=await api(`/api/research-projects/${selectedResearchProject.id}/material-comparisons/${index}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});selectedResearchProject.material_comparisons[index]=result.comparison;if(currentComparison?._recordIndex===index)currentComparison={...result.comparison,_saved:true,_researchProjectId:selectedResearchProject.id,_recordIndex:index};renderComparisonHistory();toast('比较结果已重命名')}catch(e){input.replaceWith(button);toast(e.message)}}}
async function deleteComparison(index){const record=comparisonRecords()[index];if(!selectedResearchProject||!record)return;closeComparisonHistory();if(!confirm(`删除“${comparisonRecordLabel(record,index)}”？`))return;try{await api(`/api/research-projects/${selectedResearchProject.id}/material-comparisons/${index}`,{method:'DELETE'});selectedResearchProject.material_comparisons.splice(index,1);if(currentComparison?._recordIndex===index){currentComparison=null;$('#comparisonPanel').innerHTML='<div class="memo-empty">请选择材料开始比较</div>';$('#saveComparisonBtn').disabled=true}else if(currentComparison?._recordIndex>index)currentComparison._recordIndex--;renderComparisonHistory();toast('比较记录已删除')}catch(e){toast(e.message)}}
async function openComparisonEvidence(projectId,number){try{switchFamiliarityMode('memo');await openProject(projectId,{type:'workspace',key:String(projectId)});switchView('analysis','familiarity');renderMemoSource(number)}catch(e){toast(e.message)}}
function renderCodes(){const box=$('#codeList');const codes=analysisData?.codes||[];box.innerHTML=codes.length?codes.map(c=>`<div class="mini-item ${c.id===selectedCodeId?'selected':''}" data-code="${c.id}"><b>${escapeHtml(c.name)}</b><small>${escapeHtml(c.theme?c.theme+' · ':'')}${escapeHtml(c.definition||'暂无定义')}</small></div>`).join(''):'<div class="empty">尚无编码</div>';box.querySelectorAll('[data-code]').forEach(el=>el.onclick=()=>{selectedCodeId=el.dataset.code;renderCodes()});const filter=$('#evidenceFilter'),old=filter.value;filter.innerHTML='<option value="">全部编码</option>'+codes.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('');filter.value=old;const picker=$('#codingPopoverSelect');if(picker)picker.innerHTML='<option value="">选择已有编码</option>'+codes.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('')}
function renderSuggestions(){const box=$('#suggestionList'),items=analysisData?.ai_suggestions||[];box.innerHTML=items.length?items.map(s=>`<div class="mini-item suggestion-item"><div><b>${escapeHtml(s.code)}</b><small>${escapeHtml(s.quote)}</small><small>${escapeHtml(s.reason||'')}</small></div>${s.status==='已接受'?'<span>已接受</span>':`<button class="soft" data-accept="${s.id}">接受</button>`}</div>`).join(''):'<div class="empty">尚无AI建议</div>';box.querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>acceptSuggestion(b.dataset.accept))}
function renderEvidence(){const codeMap=Object.fromEntries((analysisData?.codes||[]).map(c=>[c.id,c])),filter=$('#evidenceFilter').value;const rows=(analysisData?.excerpts||[]).filter(e=>!filter||e.code_id===filter);$('#evidenceList').innerHTML=rows.length?rows.map(e=>`<article class="evidence-card" data-start="${e.start??-1}"><header><b>${escapeHtml(codeMap[e.code_id]?.name||'')}</b><span>${escapeHtml(e.speaker||'')} · ${escapeHtml(e.status||'')}</span></header><blockquote>${escapeHtml(e.quote)}</blockquote><small>${escapeHtml(e.source||'')}</small></article>`).join(''):'<div class="empty">尚无已确认的原文证据</div>'}
function addCode(name,definition='',createdBy='人工'){let code=analysisData.codes.find(c=>c.name===name);if(!code){code={id:uid(),name,definition,theme:'',created_by:createdBy};analysisData.codes.push(code)}return code}
function clearCodingMark(){const mark=$('#codingText mark.coding-selection');if(mark){mark.replaceWith(...mark.childNodes);$('#codingText').normalize()}}
function showCodingPopover(event){clearCodingMark();const root=$('#codingText'),selection=window.getSelection();if(!selection||selection.rangeCount===0||selection.isCollapsed)return hideCodingPopover();const range=selection.getRangeAt(0);if(!root.contains(range.commonAncestorContainer))return hideCodingPopover();const before=range.cloneRange();before.selectNodeContents(root);before.setEnd(range.startContainer,range.startOffset);const start=before.toString().length,quote=range.toString(),end=start+quote.length;if(!quote.trim())return hideCodingPopover();codingSelection={start,end,quote:quote.trim()};const mark=document.createElement('mark');mark.className='coding-selection';try{range.surroundContents(mark)}catch{return hideCodingPopover()}selection.removeAllRanges();const pop=$('#codingPopover'),rect=mark.getBoundingClientRect(),x=event?.clientX||rect.left,y=event?.clientY||rect.bottom;pop.style.left=Math.max(12,Math.min(x,window.innerWidth-470))+'px';pop.style.top=Math.max(12,Math.min(y+12,window.innerHeight-90))+'px';pop.hidden=false;$('#codingPopoverSelect').value=selectedCodeId||'';$('#codingPopoverInput').value=''}
function hideCodingPopover(){codingSelection=null;$('#codingPopover').hidden=true;clearCodingMark()}
function toggleCodingText(){hideCodingPopover();const collapsed=$('#codingGrid').classList.toggle('text-collapsed'),button=$('#toggleCodingTextBtn');button.textContent=collapsed?'▶':'◀';button.title=button.ariaLabel=collapsed?'展开访谈稿':'收起访谈稿'}
async function applyPopoverCode(){if(!codingSelection)return;const newName=$('#codingPopoverInput').value.trim(),chosen=$('#codingPopoverSelect').value;let code;if(newName)code=addCode(newName,'','人工');else code=analysisData.codes.find(c=>c.id===chosen);if(!code){toast('请选择已有编码或输入新编码');return}selectedCodeId=code.id;const text=codingTextValue(),{start,end,quote}=codingSelection,before=text.slice(0,start),matches=[...before.matchAll(/(说话人\d+)\s*[：:]/g)],speaker=matches.length?matches.at(-1)[1]:'';analysisData.excerpts.push({id:uid(),code_id:code.id,quote,context:text.slice(Math.max(0,start-100),Math.min(text.length,end+100)),speaker,source:'人工划线',status:'已确认',start});hideCodingPopover();await saveAnalysis(false);renderAnalysis();toast('原文已编码')}
async function requestAiCodes(){if(!selected){toast('请先选择项目');return}const button=$('#aiCodeBtn');setAiLoading(button,true);$('#codingStatus').textContent='正在生成…';try{await saveAnalysis(false);const question=selectedResearchProject?.research_question||analysisData?.metadata?.research_question||'';const r=await api(`/api/projects/${selected}/coding-suggestions`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({research_question:question})});const known=new Set(analysisData.ai_suggestions.map(s=>s.quote+'|'+s.code));analysisData.ai_suggestions.push(...r.suggestions.filter(s=>!known.has(s.quote+'|'+s.code)));await saveAnalysis(false);renderSuggestions();$('#codingStatus').textContent=`已生成 ${r.suggestions.length} 条建议`;toast('AI编码建议已生成')}catch(e){$('#codingStatus').textContent='生成失败：'+e.message;toast(e.message)}finally{setAiLoading(button,false)}}
async function acceptSuggestion(id){const s=analysisData.ai_suggestions.find(x=>x.id===id);if(!s||s.status==='已接受')return;const code=addCode(s.code,s.reason||'','AI');const text=codingTextValue(),start=text.indexOf(s.quote);analysisData.excerpts.push({id:uid(),code_id:code.id,quote:s.quote,context:start>=0?text.slice(Math.max(0,start-100),Math.min(text.length,start+s.quote.length+100)):s.quote,speaker:s.speaker||'',source:'AI建议',status:'人工已确认',start});s.status='已接受';await saveAnalysis(false);renderAnalysis();toast('已接受该编码建议')}
async function setTheme(){if(!selectedCodeId){toast('请先在编码工作区选择编码');return}const c=analysisData.codes.find(x=>x.id===selectedCodeId),theme=prompt(`为“${c.name}”设置主题：`,c.theme||'');if(theme===null)return;c.theme=theme.trim();await saveAnalysis(false);renderAnalysis()}
