$('#editorImportToggle').onclick=()=>toggleEditorMenu('import');$('#acceptMenuToggle').onclick=()=>toggleEditorMenu('accept');$('#editorImportText').onclick=()=>{closeEditorMenu('import');$('#transcriptDialog').showModal()};$('#editorImportAudio').onclick=()=>{closeEditorMenu('import');$('#projectDialog').showModal()};document.addEventListener('click',event=>{if(!event.target.closest('.editor-menu-wrap'))closeEditorMenu('import');if(!event.target.closest('.editor-ai-split'))closeEditorMenu('accept')});
$('#generateMemoBtn').onclick=generateMemo;$('#saveMemoBtn').onclick=saveMemo;$('#memoInterviewSelect').onchange=e=>{const option=e.target.selectedOptions[0];if(option?.value==='choose-project'){renderMemoSwitcher();openMemoProjectPicker();return}if(option?.dataset.type)openMaterialMemo(option.dataset.type,option.dataset.key)};$('#closeMemoProjectDialog').onclick=$('#cancelMemoProjectDialog').onclick=()=>$('#memoProjectDialog').close();$('#addEditorProjectBtn').onclick=openEditorProjectDialog;$('#closeAddEditorProjectDialog').onclick=$('#cancelAddEditorProjectDialog').onclick=()=>$('#addEditorProjectDialog').close();
$('#memoModeBtn').onclick=()=>switchFamiliarityMode('memo');$('#comparisonModeBtn').onclick=()=>switchFamiliarityMode('comparison');$('#compareMaterialsBtn').onclick=openComparisonDialog;$('#emptyComparisonBtn').onclick=openComparisonDialog;$('#saveComparisonBtn').onclick=saveComparison;$('#comparisonHistoryToggle').onclick=()=>{const list=$('#comparisonHistoryList');list.hidden=!list.hidden;$('#comparisonHistoryToggle').setAttribute('aria-expanded',String(!list.hidden))};document.addEventListener('click',event=>{if(!event.target.closest('.comparison-history'))closeComparisonHistory()});$('#closeComparisonDialog').onclick=$('#cancelComparisonDialog').onclick=()=>$('#comparisonDialog').close();$('#comparisonMaterialList').onchange=updateComparisonCount;$('#startComparisonBtn').onclick=generateComparison;
$('#createResearchBtn').onclick=()=>openResearchDialog(selectedResearchProject?'add':'create');$('#researchBackBtn').onclick=showResearchList;$('#deleteResearchBtn').onclick=()=>selectedResearchProject&&deleteResearchProject(selectedResearchProject.id);$('#closeResearchDialog').onclick=$('#cancelResearchDialog').onclick=()=>$('#researchDialog').close();
$('#researchTranscriptInput').onchange=e=>{$('#researchTranscriptLabel').textContent=[...e.target.files].map(file=>file.name).join('、')||'TXT 或 DOCX'};
$('#projectForm').onsubmit=async e=>{e.preventDefault();const btn=$('#submitProject');btn.disabled=true;btn.textContent='正在导入…';try{await api('/api/projects',{method:'POST',body:new FormData(e.target)});$('#projectDialog').close();e.target.reset();$('#fileLabel').textContent='选择录音文件';toast('已开始转录');await refresh();startPolling()}catch(err){toast(err.message)}finally{btn.disabled=false;btn.textContent='开始转录'}};
$('#transcriptForm').onsubmit=async e=>{e.preventDefault();const btn=$('#submitTranscript');btn.disabled=true;btn.textContent='导入中…';try{const project=await api('/api/transcript-projects',{method:'POST',body:new FormData(e.target)});$('#transcriptDialog').close();e.target.reset();$('#transcriptFileLabel').textContent='选择 TXT 或 Word 访谈稿';await loadProjects();toast('访谈稿已导入');await openProject(project.id)}catch(err){toast(err.message)}finally{btn.disabled=false;btn.textContent='导入'}};
$('#researchForm').onsubmit=async e=>{e.preventDefault();const adding=researchDialogMode==='add',btn=$('#submitResearch'),form=new FormData(e.target),ids=form.getAll('interview_ids');form.delete('interview_ids');form.append('interview_ids',JSON.stringify(ids));btn.disabled=true;btn.textContent=adding?'添加中…':'创建中…';try{await api(adding?`/api/research-projects/${selectedResearchProject.id}/materials`:'/api/research-projects',{method:'POST',body:form});$('#researchDialog').close();e.target.reset();$('#researchTranscriptLabel').textContent='TXT 或 DOCX';await loadResearchProjects();if(adding){openResearchProject(selectedResearchProject.id);toast('资料已添加')}else{showResearchList();toast('研究项目已创建')}}catch(err){toast(err.message)}finally{btn.disabled=false;btn.textContent=adding?'添加':'创建项目'}};
async function refresh(){await Promise.all([loadStatus(),loadProjects(),loadResearchProjects()])}function startPolling(){clearInterval(pollTimer);pollTimer=setInterval(async()=>{await refresh();if(!projects.some(p=>['queued','running'].includes(p.status)))clearInterval(pollTimer)},5000)}refresh().then(()=>{if(projects.some(p=>['queued','running'].includes(p.status)))startPolling()}).catch(e=>toast(e.message));
